'use strict';
const VIBE_CATEGORIES={all:'All reactions',motivation:'Encouragement',meal:'Food logs',movement:'Tiny moves',water:'Water check-ins',budget:'Budget & plans',rest:'Slow days',progress:'Small wins'};
let vibeGalleryFilter='all',activeVibeReason='progress',activeVibePhotoId=null;
function vibeImagesEnabled(){return state.platinum===true&&state.coachType==='kaincheck'&&state.coach.vibe===true;}
function vibeMoment(){const saved=state.vibePhotos||{};return saved.day===localDay()?{reason:Object.hasOwn(VIBE_CATEGORIES,saved.reason)&&saved.reason!=='all'?saved.reason:'motivation',offset:Math.max(0,Number(saved.offset)||0)}:{reason:'motivation',offset:0};}
function setVibeMoment(reason,persist=false){if(!vibeImagesEnabled())return;const current=vibeMoment();state.vibePhotos={day:localDay(),reason:reason==='plan'?'budget':Object.hasOwn(VIBE_CATEGORIES,reason)&&reason!=='all'?reason:'motivation',offset:(current.offset+1)%10000};if(persist)save();}
function pickVibePhoto(reason='motivation',offset=vibeMoment().offset){const pool=VIBE_PHOTOS.filter(p=>p.tags.includes(reason)),photos=pool.length?pool:VIBE_PHOTOS,seed=localDay()+'|'+(state.coach.templateId||'kai')+'|'+reason;let hash=0;for(const char of seed)hash=(hash*31+char.charCodeAt(0))>>>0;return photos[(hash+offset)%photos.length];}
function vibePhotoImage(photo,className=''){return `<img class="${className}" data-vibe-image="${photo.id}" src="${photo.image}" alt="${esc(photo.alt)}" loading="lazy" decoding="async">`;}
function dailyVibeMarkup(){if(!vibeImagesEnabled())return '';const moment=vibeMoment(),photo=pickVibePhoto(moment.reason);return `<section class="daily-vibe" aria-label="Daily Vibe"><button class="daily-vibe-picture" data-open-vibe="${photo.id}" aria-label="Open this Vibe reaction">${vibePhotoImage(photo)}</button><div class="daily-vibe-copy"><small class="vibe-reaction-label">✨ VIBE MODE · JUST FOR FUN</small><h2>${VIBE_CATEGORIES[moment.reason]}</h2><p>${esc(photo.caption)}</p><div class="vibe-reaction-actions"><button class="text-btn" data-action="shuffle-vibe">Another vibe</button><button class="text-btn" data-action="vibe-gallery">Browse photos</button></div></div></section>`;}
function openVibeGallery(filter='all'){if(!vibeImagesEnabled()){toast('Turn on Vibe Mode in your KainCheck coach settings to see animal reactions.');return;}vibeGalleryFilter=Object.hasOwn(VIBE_CATEGORIES,filter)?filter:'all';const photos=VIBE_PHOTOS.filter(p=>vibeGalleryFilter==='all'||p.tags.includes(vibeGalleryFilter));showModal('Your Vibe Gallery',`<p class="subtle">A little animal-powered encouragement. Open a reaction whenever you want a lighter moment.</p><div class="filters vibe-gallery-filters" role="group" aria-label="Reaction categories">${Object.entries(VIBE_CATEGORIES).map(([id,label])=>`<button class="chip ${vibeGalleryFilter===id?'selected':''}" data-vibe-filter="${id}" aria-pressed="${vibeGalleryFilter===id}">${label}</button>`).join('')}</div><div class="vibe-photo-gallery">${photos.map(p=>`<button class="vibe-gallery-tile" data-open-vibe="${p.id}" aria-label="Open reaction: ${esc(p.alt)}">${vibePhotoImage(p)}<span>${esc(p.caption)}</span></button>`).join('')}</div><p class="vibe-gallery-note">These are playful reactions. Food guidance and nutrition cautions stay in your food log.</p>`);activeModal='vibe-gallery';}
function showAnimalVibe(reason='progress',photoId=null){if(!vibeImagesEnabled()){toast('Vibe Mode is off. You can enable it in your KainCheck coach settings.');return;}activeVibeReason=Object.hasOwn(VIBE_CATEGORIES,reason)&&reason!=='all'?reason:'progress';const photo=VIBE_PHOTOS.find(p=>p.id===photoId)||pickVibePhoto(activeVibeReason);activeVibePhotoId=photo.id;showModal('Your Vibe card',`<figure class="animal-vibe-card">${vibePhotoImage(photo)}<figcaption><small class="vibe-reaction-label">✨ VIBE MODE · JUST FOR FUN</small><h3>${VIBE_CATEGORIES[activeVibeReason]}</h3><p>${esc(photo.caption)}</p></figcaption></figure><p class="subtle">A playful check-in, at your own pace.</p><div class="sheet-actions"><button class="secondary" data-action="vibe-gallery">Browse photos</button><button class="primary" data-action="shuffle-vibe">Another reaction</button></div><button class="text-btn vibe-card-done" data-action="close">Done</button>`);activeModal='vibe-photo';}
function vibeSensitiveTopic(text){return /sodium|salt|sugar|allerg|diabet|kidney|blood.?pressure|hypertens|heart|pregnan|medic|doctor|clinician|dietitian|diagnos|symptom|pain|injur|dizz|faint|vomit|nausea|unsafe|emergen|suicid|self.?harm|kill myself|hurt myself|depress|disorder|anorex|purging|calorie restriction/i.test(text);}
function decorateVibeReply(message,input){const result={...message};delete result.vibePhoto;if(!vibeImagesEnabled()||message.error||message.refreshError||vibeSensitiveTopic(String(input)+' '+String(message.text)))return result;const s=String(input).toLowerCase();if(!/goofy|meme|funny|joke|encourag|motivat|small win|good vibes|cheer me|proud/.test(s))return result;const reason=/small win|proud|celebrat/.test(s)?'progress':/budget|afford|pesos|₱/.test(s)?'budget':/water|tubig|hydrat/.test(s)?'water':/walk|move|workout|sayaw|lakad/.test(s)?'movement':'motivation';result.vibePhoto=pickVibePhoto(reason).id;return result;}
function vibeChatReactionMarkup(message){if(!vibeImagesEnabled()||message.error||message.refreshError||vibeSensitiveTopic(message.text||''))return '';const photo=VIBE_PHOTOS.find(p=>p.id===message.vibePhoto);return photo?`<figure class="chat-vibe-reaction">${vibePhotoImage(photo)}<figcaption>${esc(photo.caption)}<small>Vibe reaction · just for fun</small></figcaption></figure>`:'';}
function syncVibeVisibility(){if(!vibeImagesEnabled()&&['vibe-photo','vibe-gallery'].includes(activeModal))closeModal();}
function installVibeImages(){
 showVibe=showAnimalVibe;Object.assign(actions,{'vibe-gallery':()=>openVibeGallery(),'shuffle-vibe':()=>{if(!vibeImagesEnabled())return;const modal=activeModal==='vibe-photo',reason=modal?activeVibeReason:vibeMoment().reason;setVibeMoment(reason,true);if(modal){const pool=VIBE_PHOTOS.filter(p=>p.tags.includes(reason)),index=pool.findIndex(p=>p.id===activeVibePhotoId);showAnimalVibe(reason,pool[(index+1)%pool.length]?.id);}else render(true);}});
 const baseToday=today;today=()=>{const markup=baseToday();if(!vibeImagesEnabled())return markup;return markup.replace(/<div class="cheer">[\s\S]*?<\/div>/,'').replace('<button class="wellness-home-entry"',dailyVibeMarkup()+'<button class="wellness-home-entry"');};
 const baseCoach=coach;coach=()=>{const markup=baseCoach();return vibeImagesEnabled()?markup.replace('<div class="chat-suggestions">','<div class="chat-suggestions"><button data-prompt="Give me a little goofy encouragement for a small daily win.">Goofy encouragement</button>'):markup;};
 const baseWater=actions.water;actions.water=()=>{setVibeMoment('water');baseWater();};
 const baseComplete=completePlan;completePlan=id=>{const item=state.plan.find(p=>p.id===id);if(item&&!item.done)setVibeMoment(item.kind==='activity'?'movement':'plan');baseComplete(id);};
 document.addEventListener('click',e=>{const open=e.target.closest('[data-open-vibe]');if(open&&vibeImagesEnabled()){const photo=VIBE_PHOTOS.find(p=>p.id===open.dataset.openVibe);if(photo)showAnimalVibe(photo.tags[0],photo.id);}const filter=e.target.closest('[data-vibe-filter]');if(filter)openVibeGallery(filter.dataset.vibeFilter);});
 document.addEventListener('submit',e=>{if(e.target.id==='activity-form'&&!e.target.dataset.edit&&vibeImagesEnabled()){setVibeMoment('movement',true);if(screen==='today')render(true);}});
}
